svg.script:
(function(){
const svg=document.currentScript.ownerSVGElement;
const interactive='.gate, .channel-group, .center';
const flowControl=svg.getElementById('flow-control');
const tooltip=svg.getElementById('svg-tooltip');
const tooltipRect=tooltip.querySelector('rect');
const tooltipText=tooltip.querySelector('text');
function hideTooltip(){tooltip.classList.remove('is-visible');tooltip.setAttribute('aria-hidden','true');}
function showTooltip(item,event){
 let detail=item.getAttribute('data-tooltip')||item.getAttribute('aria-label')||'';if(!detail)return;
 if(item.matches('.gate[data-transit-planets]'))detail+=` Current transit activation: ${item.dataset.transitPlanets}.`;
 if(item.matches('.channel-group[data-transit-channel]'))detail+=' Both gates are activated by the current transits.';
 const reference=item.matches('.gate')?`Gate ${item.dataset.gate}`:`Channel ${item.dataset.channel}`;
 const words=(reference+' '+detail).split(/\s+/),lines=[];let line='';
 words.forEach(word=>{const candidate=line?line+' '+word:word;if(candidate.length>42&&line){lines.push(line);line=word;}else line=candidate;});if(line)lines.push(line);
 while(tooltipText.firstChild)tooltipText.removeChild(tooltipText.firstChild);
 lines.forEach((value,index)=>{const span=document.createElementNS('http://www.w3.org/2000/svg','tspan');span.setAttribute('x','0');span.setAttribute('dy',index?'8':'0');span.textContent=value;tooltipText.appendChild(span);});
 const width=190,height=12+lines.length*8;tooltipRect.setAttribute('width',width);tooltipRect.setAttribute('height',height);tooltipText.setAttribute('transform','translate(6 9)');
 let screenX,screenY;if(event.type==='focusin'){const box=item.getBoundingClientRect();screenX=box.left+box.width/2;screenY=box.top+box.height/2;}else{screenX=event.clientX;screenY=event.clientY;}
 const bounds=svg.getBoundingClientRect();let anchorX=(screenX-bounds.left)*360/(bounds.width||360),anchorY=(screenY-bounds.top)*360/(bounds.height||360);
 if(!Number.isFinite(anchorX))anchorX=180;if(!Number.isFinite(anchorY))anchorY=180;
 const margin=8,maxX=360-width-margin,maxY=360-height-margin;const x=maxX;let y=anchorY+12;
 if(y>maxY)y=anchorY-height-12;y=Math.max(margin,Math.min(maxY,y));
 tooltip.setAttribute('transform',`translate(${x} ${y})`);tooltip.classList.add('is-visible');tooltip.setAttribute('aria-hidden','false');
}
let showAllFlow=false;
function reverseCubic(d){const m=d.match(/^M\s*(-?[\d.]+),(-?[\d.]+)\s*C\s*(-?[\d.]+),(-?[\d.]+)\s+(-?[\d.]+),(-?[\d.]+)\s+(-?[\d.]+),(-?[\d.]+)$/);if(!m)return d;const [x0,y0,x1,y1,x2,y2,x3,y3]=m.slice(1);return `M${x3},${y3} C${x2},${y2} ${x1},${y1} ${x0},${y0}`;}
function orientChannelPaths(){
 const matrixPoint=(marker,group)=>{const point=svg.createSVGPoint();point.x=Number(marker.getAttribute('cx'));point.y=Number(marker.getAttribute('cy'));return point.matrixTransform(group.getCTM().inverse().multiply(marker.getCTM()));};
 svg.querySelectorAll('.channel-group').forEach(group=>{
  const base=group.querySelector('.channel');if(!base)return;
  const from=svg.getElementById('gate-'+group.dataset.from),to=svg.getElementById('gate-'+group.dataset.to);if(!from||!to)return;
  const fm=from.querySelector('.gate-marker'),tm=to.querySelector('.gate-marker');if(!fm||!tm)return;
  const fp=matrixPoint(fm,group),tp=matrixPoint(tm,group),length=base.getTotalLength();
  const a=base.getPointAtLength(0),b=base.getPointAtLength(length);
  const startIsFrom=Math.hypot(a.x-fp.x,a.y-fp.y)<=Math.hypot(b.x-fp.x,b.y-fp.y);
  if(!startIsFrom)group.querySelectorAll('.channel,.channel-highlight,.channel-flow,.channel-hit').forEach(path=>path.setAttribute('d',reverseCubic(path.getAttribute('d'))));
 });
}
orientChannelPaths();
function addFlowDots(){
 if(window.matchMedia('(prefers-reduced-motion: reduce)').matches)return;
 const ns='http://www.w3.org/2000/svg';
 svg.querySelectorAll('.channel-group').forEach(group=>{
  const paths=[group.querySelector('.channel-flow')];
  paths.forEach(path=>{if(!path)return;const dot=document.createElementNS(ns,'circle');dot.setAttribute('class','flow-dot flow-forward');dot.setAttribute('r','1.45');const motion=document.createElementNS(ns,'animateMotion');motion.setAttribute('dur','2.6s');motion.setAttribute('repeatCount','indefinite');motion.setAttribute('path',path.getAttribute('d'));dot.appendChild(motion);group.appendChild(dot);});
 });
}
addFlowDots();
function syncFlow(){svg.querySelectorAll('.channel-group').forEach(ch=>ch.classList.toggle('is-flowing',ch.dataset.defined==='true'&&(showAllFlow||ch.classList.contains('is-active'))));flowControl.setAttribute('aria-pressed',String(showAllFlow));flowControl.querySelector('text').textContent=showAllFlow?'Ⅱ  Pause flow':'▶  Flow';}
function updateChartState(){
 const activeCenters=new Set();
 svg.querySelectorAll('.gate').forEach(gate=>{
  const active=gate.dataset.state==='closed';gate.setAttribute('aria-pressed',String(active));
  const activation=gate.dataset.activation?` Natal activation: ${gate.dataset.activation}.`:'';
  gate.setAttribute('aria-label',`Gate ${gate.dataset.gate}: ${gate.dataset.reading||'gate activation'}. ${active?'Activated.':'Inactive.'}${activation} Click or press Enter to ${active?'deactivate':'activate'} this gate.`);
 });
 svg.querySelectorAll('.channel-group').forEach(channel=>{
  const from=svg.getElementById('gate-'+channel.dataset.from),to=svg.getElementById('gate-'+channel.dataset.to);
  const fromActive=from?.dataset.state==='closed',toActive=to?.dataset.state==='closed';
  const defined=fromActive&&toActive,incomplete=fromActive||toActive;
  channel.dataset.defined=String(defined);
  channel.setAttribute('aria-label',`Channel ${channel.dataset.channel}: ${defined?'defined; both endpoint gates are activated.':incomplete?'incomplete; one endpoint gate is activated.':'open; neither endpoint gate is activated.'}`);
  if(defined){activeCenters.add(from.dataset.center);activeCenters.add(to.dataset.center);}
 });
 svg.querySelectorAll('.center').forEach(center=>center.dataset.defined=String(activeCenters.has(center.dataset.center)));
 syncFlow();
}
function toggleGate(gate){gate.dataset.state=gate.dataset.state==='closed'?'open':'closed';updateChartState();}
function toggleFlow(){showAllFlow=!showAllFlow;syncFlow();}
flowControl.addEventListener('click',toggleFlow);
flowControl.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();toggleFlow();}});
function clear(){svg.querySelectorAll('.is-active,.is-related').forEach(el=>el.classList.remove('is-active','is-related'));syncFlow();}
function activate(el){
 clear();
 if(!el)return;
 let channels=el.matches('.channel-group')?[el]:Array.from(svg.querySelectorAll('.channel-group')).filter(ch=>ch.dataset.from===el.dataset.gate||ch.dataset.to===el.dataset.gate);
 if(el.matches('.channel-group[data-network]'))channels=Array.from(svg.querySelectorAll('.channel-group')).filter(ch=>ch.dataset.network===el.dataset.network);
 const gateIds=new Set();
 channels.forEach(ch=>{ch.classList.add('is-active');gateIds.add(ch.dataset.from);gateIds.add(ch.dataset.to);});syncFlow();
 gateIds.forEach(id=>{const gate=svg.getElementById('gate-'+id);if(gate)gate.classList.add(el.id==='gate-'+id?'is-active':'is-related');});
 svg.querySelectorAll('.center').forEach(center=>{if(Array.from(gateIds).some(id=>svg.getElementById('gate-'+id)?.dataset.center===center.dataset.center))center.classList.add('is-active');});
}
function fromTarget(target){return target instanceof Element?target.closest(interactive):null;}
function updateZoomLabels(){const zoom=svg.getScreenCTM()?.a||1;svg.querySelectorAll('.gate-number').forEach(label=>label.classList.toggle('is-zoomed',zoom>=3));}
updateZoomLabels();window.addEventListener('resize',updateZoomLabels);window.CastaliaHumanDesignTransit?.installSvg(svg);updateChartState();
svg.addEventListener('click',event=>{const gate=event.target instanceof Element?event.target.closest('.gate'):null;if(gate){event.stopPropagation();toggleGate(gate);showTooltip(gate,event);}});
svg.addEventListener('keydown',event=>{const gate=event.target instanceof Element?event.target.closest('.gate'):null;if(gate&&(event.key==='Enter'||event.key===' ')){event.preventDefault();event.stopPropagation();toggleGate(gate);showTooltip(gate,{type:'focusin'});}});
svg.addEventListener('pointerover',event=>{const item=fromTarget(event.target);if(item){activate(item);showTooltip(item,event);}});
svg.addEventListener('pointerout',event=>{const item=fromTarget(event.target);if(item&&!item.contains(event.relatedTarget)){const next=fromTarget(event.relatedTarget);if(next){activate(next);showTooltip(next,event);}else{clear();hideTooltip();}}});
svg.addEventListener('focusin',event=>{const item=fromTarget(event.target);if(item){activate(item);showTooltip(item,event);}});
svg.addEventListener('focusout',event=>{if(!fromTarget(event.relatedTarget)){clear();hideTooltip();}else{const next=fromTarget(event.relatedTarget);activate(next);showTooltip(next,event);}});
})();
